import * as THREE from 'three/webgpu';
import { texture, vec3, mul, positionLocal } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Extract config
  const { position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1], imageUrl, depthMapUrl } = config;

  // Set transform
  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  // Load textures (synchronous, cached)
  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthMapUrl);

  // Plane dimensions (based on source rect aspect: 512/320 ≈ 1.6)
  const width = 1.6;
  const height = 1.0;
  const segments = 64;

  // Geometry
  const geometry = new THREE.PlaneGeometry(width, height, segments, segments);

  // TSL material with displacement
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(colorMap);
  const dispMap = texture(depthMap);
  material.displacementNode = dispMap.mul(0.1); // subtle displacement

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Local bounding box for parallax calculation
  const halfW = width / 2;
  const halfH = height / 2;

  // Reusable GSAP kill function
  let currentTween = null;
  function killTween() {
    if (currentTween) {
      currentTween.kill();
      currentTween = null;
    }
  }

  // --- Hover: rise-in (subtle 0.15 units) ---
  function onPointerOver(/* event */) {
    killTween();
    currentTween = gsap.to(mesh.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    if (group.userData.handlers?.hover) {
      group.userData.handlers.hover('enter');
    }
  }

  function onPointerOut(/* event */) {
    killTween();
    currentTween = gsap.to(mesh.position, {
      y: 0,
      duration: 0.5,
      ease: 'power2.out',
    });
    if (group.userData.handlers?.hover) {
      group.userData.handlers.hover('leave');
    }
  }

  // --- Click: press-down + navigation ---
  function onPointerDown(event) {
    killTween();
    // Press down
    gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        // Release
        gsap.to(mesh.scale, {
          x: 1,
          y: 1,
          duration: 0.3,
          ease: 'power2.out',
        });
      },
    });

    // Emit event
    if (group.userData.handlers?.emit) {
      group.userData.handlers.emit('hub-features.select', { target: event });
    }

    // Data binding: navigate to checkout URL
    const checkoutUrl = group.userData.checkoutUrl;
    if (checkoutUrl && typeof window !== 'undefined') {
      window.location.href = checkoutUrl;
    }
  }

  // --- Parallax on pointer move (subtle rotation) ---
  function onPointerMove(event) {
    // Only act while hovering
    if (!event.isPrimary) return;
    // event.point is in world coordinates; convert to local
    const localPoint = mesh.worldToLocal(event.point.clone());
    // Normalize to [-1, 1] within plane bounds
    const xNorm = localPoint.x / halfW;
    const yNorm = localPoint.y / halfH;
    // Apply subtle rotation
    gsap.to(mesh.rotation, {
      x: yNorm * 0.02,
      y: xNorm * 0.02,
      duration: 0.3,
      overwrite: 'auto',
    });
  }

  // --- Attach native Three.js pointer events ---
  mesh.addEventListener('pointerover', onPointerOver);
  mesh.addEventListener('pointerout', onPointerOut);
  mesh.addEventListener('pointerdown', onPointerDown);
  mesh.addEventListener('pointermove', onPointerMove);

  // --- Expose handlers for parent hub ---
  group.userData.handlers = {
    hover: () => {},
    click: () => {},
    emit: (eventName, data) => {
      // Stub for event emission – parent hub will override
    },
  };

  // --- Store checkout URL from data bindings (placeholder) ---
  const binding = config.dataBindings?.find(b => b.target === 'onClick.navigate');
  group.userData.checkoutUrl = binding ? '/checkout' : null;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP tweens
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(mesh.rotation);
    // Remove event listeners
    mesh.removeEventListener('pointerover', onPointerOver);
    mesh.removeEventListener('pointerout', onPointerOut);
    mesh.removeEventListener('pointerdown', onPointerDown);
    mesh.removeEventListener('pointermove', onPointerMove);
    // Dispose GPU resources
    material.dispose();
    geometry.dispose();
    // Remove from scene
    if (group.parent) {
      group.parent.remove(group);
    }
  };

  return group;
}
